import{_ as t,o as n,c as o,a0 as s}from"./chunks/framework.Ckbw5VQO.js";const r="/geo-ml/documentation/learning/deep-learning/cnn/19_cnn.png",a="/geo-ml/documentation/learning/deep-learning/cnn/09_conv2d.png",i="/geo-ml/documentation/learning/deep-learning/cnn/relu.svg",l="/geo-ml/documentation/learning/deep-learning/cnn/20_cnn.svg",c="/geo-ml/documentation/learning/deep-learning/cnn/arch-lenet5.svg",u="/geo-ml/documentation/learning/deep-learning/cnn/arch-vgg.svg",d="/geo-ml/documentation/learning/deep-learning/cnn/arch-resnet.svg",x=JSON.parse(`{"title":"L'architecture","description":"","frontmatter":{},"headers":[],"relativePath":"fr/learning/deep-learning/cnn/architecture.md","filePath":"fr/learning/deep-learning/cnn/architecture.md"}`),p={name:"fr/learning/deep-learning/cnn/architecture.md"};function m(g,e,h,f,b,v){return n(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="l-architecture" tabindex="-1">L&#39;architecture <a class="header-anchor" href="#l-architecture" aria-label="Permalink to &quot;L&#39;architecture&quot;">​</a></h1><p>Un CNN (<em>ConvNet</em>, réseau de neurones convolutif) empile toujours les mêmes briques, dans le même ordre :</p><img src="'+r+'" style="display:block;margin:0 auto;width:100%;height:auto;"><p>La première moitié <strong>extrait des motifs</strong> de plus en plus abstraits (bords → textures → formes → objets) ; la seconde <strong>décide</strong> à quelle classe ils correspondent.</p><h2 id="couche-de-convolution" tabindex="-1">Couche de convolution <a class="header-anchor" href="#couche-de-convolution" aria-label="Permalink to &quot;Couche de convolution&quot;">​</a></h2><p>Une <strong>couche de convolution</strong> est l&#39;empilement de N filtres appris ensemble. Chaque filtre (petite matrice de poids, typiquement 3×3) glisse sur l&#39;entrée et produit une <em>feature map</em> ; les N feature maps empilées forment la sortie de la couche.</p><img src="'+a+'" style="display:block;margin:0 auto;width:100%;height:auto;"><p>Trois paramètres définissent la couche :</p><ul><li><strong>Nombre de filtres</strong> (<code>out_channels</code>) : combien de motifs différents on cherche. C&#39;est la profondeur de la sortie.</li><li><strong>Taille du noyau</strong> (<code>kernel_size</code>, ex. 3×3) : l&#39;étendue locale que chaque filtre regarde.</li><li><strong>Padding / stride</strong> : le padding garde la résolution stable ; le stride saute des positions pour réduire la taille.</li></ul><div class="tip custom-block"><p class="custom-block-title">Le nombre de filtres ≠ les canaux d&#39;entrée</p><p>Sur une image RGB, l&#39;entrée a <strong>3 canaux</strong> (<code>in_channels</code>). Une couche peut produire <strong>64 feature maps</strong> (<code>out_channels</code>) : chaque filtre voit les 3 canaux à la fois, mais on en empile 64 pour obtenir 64 vues différentes. Les deux dimensions sont indépendantes.</p></div><h2 id="relu" tabindex="-1">ReLU <a class="header-anchor" href="#relu" aria-label="Permalink to &quot;ReLU&quot;">​</a></h2><p>Après chaque convolution, une fonction d&#39;activation <strong>ReLU</strong> (<em>Rectified Linear Unit</em>) est appliquée pixel par pixel : <code>f(x) = max(0, x)</code>. Elle remet à zéro les valeurs négatives et laisse passer les positives.</p><img src="'+i+'" style="display:block;margin:0 auto;width:100%;height:auto;"><div class="info custom-block"><p class="custom-block-title">Pourquoi c&#39;est indispensable</p><p>La convolution est une opération <strong>linéaire</strong>. Empiler dix convolutions linéaires les unes après les autres reviendrait mathématiquement à <strong>une seule</strong> transformation linéaire — aucun gain. ReLU introduit une <strong>non-linéarité</strong> entre les couches : c&#39;est ce qui permet au réseau d&#39;apprendre des relations complexes (formes, textures, objets) et pas seulement des combinaisons linéaires de pixels.</p></div><p>ReLU a remplacé les anciennes activations (<code>tanh</code>, <code>sigmoid</code>) car son gradient ne sature pas pour les grandes valeurs : l&#39;entraînement converge bien plus vite et les couches profondes apprennent réellement.</p><h2 id="couche-de-pooling" tabindex="-1">Couche de pooling <a class="header-anchor" href="#couche-de-pooling" aria-label="Permalink to &quot;Couche de pooling&quot;">​</a></h2><p>Une <strong>couche de pooling</strong> réduit la résolution spatiale d&#39;une feature map sans rien apprendre. C&#39;est la deuxième brique fondamentale après la convolution.</p><div class="tip custom-block"><p class="custom-block-title">Trois choses qu&#39;elle fait pour le réseau</p><ul><li><strong>Réduit la taille</strong> des feature maps d&#39;un facteur 2 typiquement, ce qui allège les couches suivantes.</li><li><strong>Introduit une invariance</strong> à de petits décalages : un motif détecté en position (10, 12) reste détectable s&#39;il glisse en (11, 13).</li><li><strong>Aucun poids à apprendre</strong> : c&#39;est juste une opération de réduction, gratuite à entraîner.</li></ul></div><details class="details custom-block"><summary>Pourquoi pooler ?</summary><p>Une couche de convolution garde la même résolution que son entrée (avec padding <code>same</code>). Sans pooling, une image 256×256 reste 256×256 à toutes les profondeurs, et le réseau garde 65 536 positions à traiter par filtre. Très vite :</p><ul><li>Le calcul explose : chaque couche ajoute son cube <code>H × W × N</code> à traiter.</li><li>Le récepteur reste local : un neurone profond ne voit toujours qu&#39;un voisinage de quelques pixels.</li></ul></details><p>Le pooling prend une fenêtre (typiquement 2×2) et la réduit à <strong>une valeur</strong>. Deux stratégies coexistent :</p><img src="'+l+'" style="display:block;margin:0 auto;width:100%;height:auto;"><ul><li><strong>Max pooling</strong> garde la plus grande activation, donc le motif <strong>le plus saillant</strong> de la fenêtre. C&#39;est le défaut dans 90 % des CNN modernes.</li><li><strong>Average pooling</strong> moyenne les valeurs, lisse la feature map. Utilisé en bout de réseau (<em>global average pooling</em>) pour résumer chaque carte en un scalaire avant la classification.</li></ul><details class="details custom-block"><summary>Dropout : l&#39;astuce de régularisation associée</summary><p>Souvent placé près du pooling dans les blocs profonds, le <strong>Dropout</strong> complète la régularisation :</p><ul><li>Pendant l&#39;entraînement, à chaque batch, on <strong>désactive aléatoirement</strong> une fraction <code>p</code> des neurones (typiquement 0.2 à 0.5).</li><li>À l&#39;inférence, tous les neurones sont actifs.</li><li>Effet : le réseau ne peut pas trop dépendre d&#39;un neurone particulier → moins d&#39;overfitting.</li></ul><p>Pooling et Dropout travaillent ensemble : le pooling réduit le <strong>nombre de positions</strong>, le Dropout force le réseau à <strong>distribuer l&#39;information</strong> entre neurones.</p></details><h2 id="couche-fully-connected-dense" tabindex="-1">Couche fully connected (dense) <a class="header-anchor" href="#couche-fully-connected-dense" aria-label="Permalink to &quot;Couche fully connected (dense)&quot;">​</a></h2><p>À la fin de l&#39;extraction, les feature maps sont <strong>aplaties</strong> (<em>flatten</em>) en un grand vecteur, puis passées dans une ou plusieurs couches <strong>denses</strong> où chaque neurone est connecté à tous les précédents. C&#39;est là que le réseau combine les motifs détectés pour décider.</p><div class="warning custom-block"><p class="custom-block-title">Le gros des paramètres est ici</p><p>Dans les architectures anciennes (AlexNet, VGG), les couches denses concentrent l&#39;écrasante majorité des paramètres (ex. ~123 M des 138 M de VGG). Les architectures modernes (ResNet) les remplacent largement par du <em>global average pooling</em>, beaucoup plus léger.</p></div><h2 id="softmax-couche-de-sortie" tabindex="-1">Softmax (couche de sortie) <a class="header-anchor" href="#softmax-couche-de-sortie" aria-label="Permalink to &quot;Softmax (couche de sortie)&quot;">​</a></h2><p>Pour la classification, la dernière couche dense produit un score brut par classe (<em>logits</em>). <strong>Softmax</strong> les transforme en <strong>probabilités</strong> : toutes positives et de somme égale à 1.0. La classe retenue est celle de plus forte probabilité, qui sert aussi de <strong>score de confiance</strong>.</p><p>Pour une classification binaire (arbre / pas arbre) ou une segmentation pixel à pixel, on utilise plutôt <strong>sigmoïde</strong> (une probabilité indépendante par sortie).</p><h2 id="architectures-connues-qui-empilent-ces-briques" tabindex="-1">Architectures connues qui empilent ces briques <a class="header-anchor" href="#architectures-connues-qui-empilent-ces-briques" aria-label="Permalink to &quot;Architectures connues qui empilent ces briques&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Architecture</th><th>Année</th><th>Particularité</th></tr></thead><tbody><tr><td>LeNet-5</td><td>1998</td><td>Le pionnier, 7 couches, classification de chiffres</td></tr><tr><td>AlexNet</td><td>2012</td><td>A relancé le deep learning</td></tr><tr><td>VGG</td><td>2014</td><td>Filtres 3×3 partout, beaucoup de profondeur</td></tr><tr><td>GoogLeNet</td><td>2014</td><td>Modules « Inception », branches parallèles</td></tr><tr><td>ResNet</td><td>2015</td><td>Skip connections, jusqu&#39;à 152 couches</td></tr><tr><td>U-Net</td><td>2015</td><td>Encodeur-décodeur pour la segmentation</td></tr></tbody></table><p>Trois jalons montrent comment ces briques s&#39;assemblent et évoluent.</p><h3 id="lenet-5-le-schema-fondateur" tabindex="-1">LeNet-5 : le schéma fondateur <a class="header-anchor" href="#lenet-5-le-schema-fondateur" aria-label="Permalink to &quot;LeNet-5 : le schéma fondateur&quot;">​</a></h3><img src="'+c+'" style="display:block;margin:0 auto;width:100%;height:auto;"><h3 id="vgg-la-profondeur-par-des-3×3" tabindex="-1">VGG : la profondeur par des 3×3 <a class="header-anchor" href="#vgg-la-profondeur-par-des-3×3" aria-label="Permalink to &quot;VGG : la profondeur par des 3×3&quot;">​</a></h3><img src="'+u+'" style="display:block;margin:0 auto;width:100%;height:auto;"><h3 id="resnet-la-skip-connection" tabindex="-1">ResNet : la skip connection <a class="header-anchor" href="#resnet-la-skip-connection" aria-label="Permalink to &quot;ResNet : la skip connection&quot;">​</a></h3><img src="'+d+'" style="display:block;margin:0 auto;width:100%;height:auto;">',38)])])}const _=t(p,[["render",m]]);export{x as __pageData,_ as default};
